// expect: exit 0
// screen: 0 7 9 5 1
// screen: 1 9 0 -3 -1
// screen: 2 1 0 1
int calls;
int touch(void)
{
    calls++;
    return 1;
}
int main(void)
{
    int x;
    cls();
    printf("%d %d %d %d\n", 1 + 2 * 3, (1 + 2) * 3, 10 - 2 - 3, 7 >> 1 + 1);
    printf("%d %d %d %d\n", 1 << 3 | 1, 6 & 3 == 2, -7 / 2, -7 % 2);
    x = 0 && touch();
    x = 1 || touch();
    printf("%d %d ", x, calls);
    x = 1 && touch();
    printf("%d\n", calls);
    return 0;
}
